// Fixed, locally synthesized terminal phrases. No credentials or user text are spoken.
(()=>{
 const clips={"intro":"data:audio/mpeg;base64,","granted":"data:audio/mpeg;base64,","denied":"data:audio/mpeg;base64,"};
 const gate=document.getElementById('club-gate'),button=document.getElementById('terminal-voice');
 let enabled=true,current=null,introPlayed=false,serial=0;
 try{enabled=JSON.parse(localStorage.getItem('binottoland-terminal-voice'))!==false}catch{}
 function update(){button.textContent=enabled?'VOICE ON':'VOICE OFF';button.setAttribute('aria-pressed',String(enabled));button.setAttribute('aria-label',enabled?'Disattiva voce del terminale':'Attiva voce del terminale')}
 function stop(){serial++;if(current){current.pause();current=null}}
 function speak(kind){
  if(!enabled||!clips[kind])return;
  stop();const epoch=serial;
  try{
   const audio=new Audio(clips[kind]);current=audio;audio.volume=.7;
   audio.addEventListener('playing',()=>{if(!enabled||epoch!==serial){audio.pause();return}if(kind==='intro')introPlayed=true});
   audio.addEventListener('ended',()=>{if(epoch===serial)current=null});
   const started=audio.play();started?.catch(()=>{if(epoch===serial)current=null});
  }catch{}
 }
 window.binottolandTerminalVoice=speak;
 function introduce(event){if(!enabled||introPlayed||gate.hidden||event.target.closest?.('#terminal-voice'))return;speak('intro')}
 gate.addEventListener('pointerdown',introduce,{capture:true});
 gate.addEventListener('keydown',event=>{if(!event.ctrlKey&&!event.metaKey&&!event.altKey)introduce(event)},{capture:true});
 button.onclick=()=>{enabled=!enabled;if(!enabled)stop();else speak('intro');try{localStorage.setItem('binottoland-terminal-voice',JSON.stringify(enabled))}catch{}update()};
 window.addEventListener('pagehide',stop);update();speak('intro');
})();
